#pragma once
#include "../events/bus.h"

namespace P64::GlobalScript
{
  typedef void(*Func)();

  enum class HookType
  {
    GAME_INIT = 0,

    // Loading / Unloading
    SCENE_PRE_LOAD,
    SCENE_POST_LOAD,
    SCENE_PRE_UNLOAD,
    SCENE_POST_UNLOAD,

    // Logic
    SCENE_UPDATE,

    // Drawing
    SCENE_PRE_DRAW,
    SCENE_PRE_DRAW_3D,
    SCENE_POST_DRAW_3D,

    SCENE_DRAW_2D,

    _size_,
  };

  void callHooks(HookType type);

  // Fork: event graph. Generated by the build (src/p64/globalScriptTable.cpp): listens to the
  // global::System.Pin event of every input pin declared with P64_GLOBAL_EVENTS_IN.
  void registerEventPins();
}

/**
 * Fork: event graph (docs/todo/event-graph/PLAN.md, section 5.5).
 * Declares input pins of a named system in a global script. Pin X of system S is the event
 * global::S.X. Handle them in one function per system:
 *   P64_GLOBAL_EVENTS_IN(Save, Requested, Clear);
 *   void onInput(SaveIn input, const P64::Events::Event& ev)
 */
#define P64_GLOBAL_EVENTS_IN(System, ...) enum class System##In : uint8_t { __VA_ARGS__ };

/**
 * Declares output pins of a named system in a global script, and a fire() for them:
 *   P64_GLOBAL_EVENTS_OUT(LevelDriver, TransitionStarted, TransitionFinished);
 *   fire(LevelDriverOut::TransitionStarted, levelHash);
 */
#define P64_GLOBAL_EVENTS_OUT(System, ...) \
  enum class System##Out : uint8_t { __VA_ARGS__ }; \
  inline constexpr auto System##OutIds = ::P64::Events::Detail::systemPinHashes< \
    ::P64::Events::Detail::countPins(#__VA_ARGS__)>("global::" #System ".", #__VA_ARGS__); \
  [[maybe_unused]] inline void fire(System##Out pin, uint32_t value = 0, uint16_t sender = 0) { \
    ::P64::Events::post(::P64::Events::EventId{System##OutIds[static_cast<uint8_t>(pin)], \
                        ::P64::Events::Scope::Global, 0}, value, sender); \
  }
